# ============================================================================
#  Facet - one-shot installer
#
#  Writes every source file, installs dependencies, and vendors three.js.
#  Run from the project root:
#
#      powershell -ExecutionPolicy Bypass -File .\install-facet.ps1
#
#  Each file is embedded as base64 and decoded to exact bytes, so nothing can
#  be truncated or mangled by copy-paste or a text-encoding mismatch.
#  Your .env is never touched.
#
#  To see what it will write without running it:
#      Select-String "Write-FacetFile" install-facet.ps1 | % { ($_ -split "'")[1] }
# ============================================================================

$ErrorActionPreference = "Stop"

function Write-FacetFile {
    param([string]$Path, [string]$B64)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($B64)
    [System.IO.File]::WriteAllBytes((Join-Path $PWD.Path $Path), $bytes)
    "{0,-32} {1,7} bytes" -f $Path, $bytes.Length
}

