Write-Host ""
Write-Host "Installing dependencies..." -ForegroundColor Cyan
npm install
if ($LASTEXITCODE -ne 0) { Write-Host "npm install failed" -ForegroundColor Red; exit 1 }

Write-Host ""
Write-Host "Vendoring three.js into public/vendor (no CDN at runtime)..." -ForegroundColor Cyan
$three = @(
  @{ src = "node_modules\three\build\three.module.js";                        dst = "public\vendor\three\build" },
  @{ src = "node_modules\three\examples\jsm\controls\OrbitControls.js";       dst = "public\vendor\three\addons\controls" },
  @{ src = "node_modules\three\examples\jsm\environments\RoomEnvironment.js"; dst = "public\vendor\three\addons\environments" }
)
foreach ($t in $three) {
    if (-not (Test-Path $t.dst)) { New-Item -ItemType Directory -Path $t.dst -Force | Out-Null }
    if (Test-Path $t.src) {
        Copy-Item $t.src $t.dst -Force
        "  copied {0}" -f (Split-Path -Leaf $t.src)
    } else {
        Write-Host ("  MISSING {0} - is three installed?" -f $t.src) -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "Verifying every file arrived complete..." -ForegroundColor Cyan
Write-Host ""
& powershell -ExecutionPolicy Bypass -File .\scripts\check-files.ps1

Write-Host ""
if (Test-Path ".env") {
    Write-Host "Your existing .env was left untouched." -ForegroundColor Green
} else {
    Write-Host "No .env yet. Copy .env.example to .env, then run: npm run wallets" -ForegroundColor Yellow
}
Write-Host ""
Write-Host "Next:  npm run wallets:status     (confirm wallets are funded and opted in)" -ForegroundColor Cyan
Write-Host "       npm run dev                (http://localhost:4020)" -ForegroundColor Cyan
Write-Host ""